spec fn nonempty(x: &[i64]) -> bool { x.len() >= 1 }

spec fn max_at_upto(x: &[i64], m: usize, n: usize) -> bool { m < n && n <= x.len() && (forall|k: usize| k < n ==> x[m] >= #[trigger] x[k]) }

spec fn max_at(x: &[i64], r: usize) -> bool { r < x.len() && (forall|k: usize| k < x.len() ==> x[r] >= #[trigger] x[k]) }

#[effects(pure)]
#[uses(nonempty, max_at_upto, max_at)]
fn myfun1(x: &[i64]) -> (r: usize)
    requires nonempty(x),
    ensures max_at(x, r),
{
    let mut m: usize = 0;
    let mut i: usize = 1;
    while i < x.len()
        invariant 1 <= i, max_at_upto(x, m, i),
        decreases x.len() - i,
    {
        if x[i] > x[m] {
            m = i;
        }
        i = i + 1;
    }
    m
}

